parameters.jsCode:
// 1. Lấy dữ liệu thô gửi lên
const body = $input.first().json.body || $input.first().json;

// 2. Chuẩn hoá Tên Khách Hàng
let rawName = (body.customerName || body.name || '').trim().replace(/\s+/g, ' ');
const words = rawName.split(' ');
if (words.length === 2 && words[0].toLowerCase() === words[1].toLowerCase()) {
  rawName = words[0];
}
const half = Math.floor(words.length / 2);
if (words.length >= 2 && words.length % 2 === 0) {
  if (words.slice(0, half).join(' ').toLowerCase() === words.slice(half).join(' ').toLowerCase()) {
    rawName = words.slice(0, half).join(' ');
  }
}

// 3. Chuẩn hoá Số Điện Thoại
let rawPhone = String(body.customerPhone || body.phone || '').trim();
let cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.startsWith('84') && cleanPhone.length > 9) {
  cleanPhone = '0' + cleanPhone.slice(2);
}

// 4. Chuẩn hoá Danh Sách Sản Phẩm
let rawItems = body.items || body.products || body.line_items || [];
if (typeof rawItems === 'string') {
  try { rawItems = JSON.parse(rawItems); } catch(e) { rawItems = []; }
}
if (!Array.isArray(rawItems) && typeof rawItems === 'object') {
  rawItems = [rawItems];
}

const cleanedItems = rawItems.map((item, idx) => {
  const parseNum = (val) => {
    if (typeof val === 'number') return val;
    if (!val) return 0;
    const cleaned = String(val).replace(/[^0-9.-]/g, '');
    return Number(cleaned) || 0;
  };

  return {
    productId: item.productId || item.id || '',
    productName: (item.productName || item.name || item.title || `Sản phẩm ${idx + 1}`).trim(),
    qty: Math.max(1, parseNum(item.qty || item.quantity || 1)),
    price: parseNum(item.price || item.unitPrice || 0),
    unit: item.unit || 'Cái',
    variant: item.variant || '',
    imageUrl: item.imageUrl || item.image || ''
  };
});

const shippingFee = Number(String(body.shippingFee || 0).replace(/[^0-9.-]/g, '')) || 0;
const paidAmount = Number(String(body.paidAmount || (body.isPaid ? 999999999 : 0)).replace(/[^0-9.-]/g, '')) || 0;
const apiKey = body.apiKey || body.dunvexApiKey || '';

return [{
  json: {
    apiKey,
    customerName: rawName,
    customerPhone: cleanPhone || rawPhone,
    customerEmail: (body.customerEmail || body.email || '').toLowerCase().trim(),
    customerAddress: body.customerAddress || body.address || '',
    note: body.note || body.customerNote || 'Đơn hàng tự động từ Website qua n8n',
    shippingFee,
    paidAmount,
    items: cleanedItems,
    deliveryLocation: body.deliveryLocation || null,
    rawDeliveryLocation: body.rawDeliveryLocation || ''
  }
}];
